// ═══ OTP AUTH ═══
// Email OTP
app.post('/api/send-otp-email',async(req,res)=>{
  const email=(req.body.email||'').trim().toLowerCase();
  if(!isEmail(email))return res.status(400).json({error:'Invalid email address'});
  if(rateLimited('em:'+email))return res.status(429).json({error:'Too many requests. Try again in 10 minutes.'});
  const code=genOTP();
  const expires=new Date(Date.now()+5*60*1000).toISOString();
  db.prepare('INSERT OR REPLACE INTO otps(phone,code,expires_at)VALUES(?,?,?)').run('em:'+email,code,expires);
  const html=`<div style="font-family:-apple-system,Segoe UI,sans-serif;max-width:480px;margin:0 auto;padding:32px 24px;background:#F5F2ED;border-radius:0">
    <div style="text-align:center"><h1 style="font-family:monospace;font-size:30px;margin:0;color:#2D2A26">Bro<span style="color:#3DAE5C">Do</span>it</h1></div>
    <h2 style="font-size:18px;margin:24px 0 8px;color:#2D2A26">Your verification code</h2>
    <p style="color:#6B665E;font-size:14px;line-height:1.5">Use this 6-digit code to sign in:</p>
    <div style="background:#fff;border:2px dashed #3DAE5C;border-radius:0;padding:20px;text-align:center;font-family:monospace;font-size:40px;font-weight:700;letter-spacing:8px;color:#2D2A26;margin:16px 0">${code}</div>
    <p style="color:#9C968D;font-size:13px">This code expires in 5 minutes. If you didn't request it, ignore this email.</p>
    <hr style="border:none;border-top:1px solid #E8E4DD;margin:24px 0">
    <p style="color:#9C968D;font-size:11px;text-align:center">Brodoit — Tasks, Books &amp; Wisdom in one place.</p>
  </div>`;
  const r=await sendEmail(email,'Your Brodoit code: '+code,html);
  if(r.ok){
    // Cookie survives iOS Safari tab kills better than localStorage. Read on / to force the OTP screen
    // even if the user's localStorage was wiped while they were in Gmail. 10-min expiry.
    // 30-min TTL (was 10) — gives generous slack for slow email delivery / multi-step iOS app switches.
    // Secure flag because brodoit.com is HTTPS-only — without it, some browsers reject the cookie on reload.
    res.set('Set-Cookie','pending_otp_email='+encodeURIComponent(email)+'; Path=/; Max-Age=1800; SameSite=Lax; Secure');
    return res.json({ok:true,message:'Check your email (and spam folder)'});
  }
  res.status(500).json({ok:false,error:'Failed to send email',detail:r.reason});
});

app.post('/api/verify-otp-email',(req,res)=>{
  const email=(req.body.email||'').trim().toLowerCase();
  const code=req.body.code,name=req.body.name||'';
  if(!isEmail(email))return res.status(400).json({error:'Invalid email'});
  const key='em:'+email;
  const otp=db.prepare('SELECT * FROM otps WHERE phone=?').get(key);
  if(!otp)return res.status(400).json({error:'No OTP sent. Request a new one.'});
  if(new Date(otp.expires_at)<new Date()){db.prepare('DELETE FROM otps WHERE phone=?').run(key);return res.status(400).json({error:'OTP expired. Request a new one.'})}
  if(otp.code!==code)return res.status(400).json({error:'Wrong code. Try again.'});
  db.prepare('DELETE FROM otps WHERE phone=?').run(key);
  let user=db.prepare('SELECT * FROM users WHERE email=?').get(email);
  let token;
  if(!user){token=genToken();db.prepare('INSERT INTO users(phone,name,email,token)VALUES(?,?,?,?)').run(key,name,email,token);user={phone:key,name,email,token}}
  else{token=user.token||genToken();db.prepare('UPDATE users SET token=?,name=COALESCE(NULLIF(?,\'\'),name)WHERE email=?').run(token,name,email);user.token=token;if(name)user.name=name}
  res.append('Set-Cookie','pending_otp_email=; Path=/; Max-Age=0; SameSite=Lax'+_secureCookie);
  setTokenCookie(res,token);
  res.json({phone:user.phone,name:user.name||name,email,token});
});

app.post('/api/verify-otp',(req,res)=>{
  const phone=cleanPhone(req.body.phone),code=req.body.code,name=req.body.name||'';
  const otp=db.prepare('SELECT * FROM otps WHERE phone=?').get(phone);
  if(!otp)return res.status(400).json({error:'No OTP sent to this number. Request a new one.'});
  if(new Date(otp.expires_at)<new Date()){db.prepare('DELETE FROM otps WHERE phone=?').run(phone);return res.status(400).json({error:'OTP expired. Request a new one.'})}
  if(otp.code!==code)return res.status(400).json({error:'Wrong code. Try again.'});
  db.prepare('DELETE FROM otps WHERE phone=?').run(phone);
  let user=db.prepare('SELECT * FROM users WHERE phone=?').get(phone);
  let token;
  if(!user){token=genToken();db.prepare('INSERT INTO users(phone,name,token)VALUES(?,?,?)').run(phone,name,token);user={phone,name,token}}
  else{token=user.token||genToken();db.prepare('UPDATE users SET token=?,name=COALESCE(NULLIF(?,\'\'),name)WHERE phone=?').run(token,name,phone);user.token=token;if(name)user.name=name}
  setTokenCookie(res,token);
  res.json({phone:user.phone,name:user.name||name,token});
});

// ═══ AI CHAT — Multi-provider (Gemini Flash free → Groq free → failover) ═══
// API keys stay on the server. The browser never sees them.
// AI keys are read live: Admin (app_settings) first, then the environment — paste a key in You → Admin, no redeploy.
function geminiKey(){try{if(global._getSetting){const v=global._getSetting('GEMINI_API_KEY');if(v)return v}}catch(e){}return process.env.GEMINI_API_KEY||''}
function groqKey(){try{if(global._getSetting){const v=global._getSetting('GROQ_API_KEY');if(v)return v}}catch(e){}return process.env.GROQ_API_KEY||''}
console.log('[ai] gemini',geminiKey()?'✅':'❌','groq',groqKey()?'✅':'❌');

// ─── LLM Provider Abstraction ─────────────────────────────────────────────
// Tries providers in order: Gemini Flash (1500 req/day free) → Groq (30 RPM free)
// Each provider returns {reply:string} or throws on failure.
const _gemini=require('./modules/gemini.js');
const _gset=k=>{try{return global._getSetting?global._getSetting(k):''}catch(e){return''}};
// When Gemini has no key, is out of prepaid credit (402) or fails, text calls go to the ElevenLabs brain
// (modules/elevenbrain.js: an ElevenLabs agent whose LLM is billed to the ElevenLabs plan).
async function _viaElevenBrain(messages,systemPrompt,why){
  const B=global._elevenBrain;
  if(!B||!B.available()||messages.some(m=>m&&m.image))throw why||new Error('no-key');
  const sys=systemPrompt||((messages.find(m=>m.role==='system')||{}).content)||'You are Bro, a warm, helpful friend inside the Brodoit app.';
  const reply=await B.ask({system:sys,messages:messages.filter(m=>m.role!=='system').map(m=>({role:m.role,content:String(m.content||'')}))});
  return{reply,provider:'elevenlabs'};
}
// v16 Bro Core: every text call goes to the open-model brain (modules/brocore, Groq). The old helpers (renamed *Legacy)
// answer only as its emergency fallback (setting BROCORE_EMERGENCY, on by default) or when Bro Core is not loaded.
// Same arguments, same return shapes ({reply,provider} / {reply,message,provider,usage}) for every caller.
const _broProvider=r=>r.emergency?String(r.model).replace(/^emergency\//,''):'groq/'+String(r.model).split('/').pop();
async function _callGemini(messages,opts={}){
  const B=global._broCore;if(!B)return _callGeminiLegacy(messages,opts);
  if(opts.imageData||messages.some(m=>m&&m.image)){if(!B.emergencyOn())throw new Error('photos need the emergency fallback');return _callGeminiLegacy(messages,opts)}
  const r=await B.chat({system:opts.systemPrompt||'',messages:messages.filter(m=>!(m&&m.role==='system'&&m.content===opts.systemPrompt)),maxTokens:opts.maxTokens||4096,purpose:opts.purpose||'util'});
  return{reply:r.text,provider:_broProvider(r)};
}
async function _callGroq(messages,{maxTokens=4096,tools,purpose}={}){
  const B=global._broCore;if(!B)return _callGroqLegacy(messages,{maxTokens,tools});
  const r=await B.chat({messages,maxTokens,tools,purpose:purpose||'util'});
  return{reply:r.text,message:r.message,provider:_broProvider(r),usage:r.usage};
}
async function _callGeminiLegacy(messages,{maxTokens=4096,systemPrompt='',imageData=null}={}){
  if(!geminiKey()||(global._geminiDownUntil||0)>Date.now())return _viaElevenBrain(messages,systemPrompt,new Error('no-key'));
  try{return await _callGeminiDirect(messages,{maxTokens,systemPrompt,imageData})}
  catch(e){
    if(e.code==='credits'||e.status===402||/402|prepay|credit|billing/i.test(String(e.message)))global._geminiDownUntil=Date.now()+3600e3;
    return _viaElevenBrain(messages,systemPrompt,e);
  }
}
async function _callGeminiDirect(messages,{maxTokens=4096,systemPrompt='',imageData=null}={}){
  if(!geminiKey())throw new Error('no-key');
  // Convert OpenAI-style messages to Gemini format (supports inline images)
  const contents=messages.filter(m=>m.role!=='system').map(m=>{
    const parts=[];
    if(m.image){parts.push({inline_data:{mime_type:m.image.mime||'image/jpeg',data:m.image.data}})}
    if(m.content)parts.push({text:m.content});
    if(!parts.length)parts.push({text:''});
    return{role:m.role==='assistant'?'model':'user',parts};
  });
  const body={contents,generationConfig:{maxOutputTokens:maxTokens,temperature:0.7}};
  if(systemPrompt)body.systemInstruction={parts:[{text:systemPrompt}]};
  // model chain lives in modules/gemini.js (Google retires ids; gemini-2.0-flash is gone)
  let j;
  try{({json:j}=await _gemini.generate(geminiKey(),body,{getSetting:_gset,timeout:50000}))}
  catch(e){console.log('[ai] Gemini error:',e.status||'',e.message);throw e}
  const text=_gemini.textOf(j);
  if(!text)throw new Error('empty response');
  return{reply:text,provider:'gemini'};
}

const GROQ_MODELS=['openai/gpt-oss-120b','qwen/qwen3.6-27b','openai/gpt-oss-20b'];
async function _callGroqLegacy(messages,{maxTokens=4096,tools}={}){
  if(!groqKey())throw new Error('no-key');
  let lastErr='';
  for(const model of GROQ_MODELS){
    const body={model,max_tokens:maxTokens,messages};
    if(tools)body.tools=tools;
    let r,j;
    for(let retry=0;retry<2;retry++){
      const ctrl=new AbortController();const tmr=setTimeout(()=>ctrl.abort(),45000);
      try{
        r=await fetch('https://api.groq.com/openai/v1/chat/completions',{
          method:'POST',signal:ctrl.signal,
          headers:{'Content-Type':'application/json','Authorization':'Bearer '+groqKey()},
          body:JSON.stringify(body)
        });
      }catch(fe){clearTimeout(tmr);if(retry<1){await new Promise(ok=>setTimeout(ok,2000));continue}lastErr='timeout';r=null;break}
      clearTimeout(tmr);
      if(r.status===429){lastErr='rate-limited on '+model;console.log('[ai] Groq 429 on',model,'— trying next');r=null;break}
      if(r.status>=500){if(retry<1){await new Promise(ok=>setTimeout(ok,2000));continue}lastErr='server error';r=null;break}
      break;
    }
    if(!r)continue;
    j=await r.json();
    if(!r.ok){const msg=(j.error&&j.error.message)||'Groq error';console.log('[ai] Groq error on',model,':',r.status,msg);lastErr=msg;continue}
    const msg=j.choices&&j.choices[0]&&j.choices[0].message;
    // Strip <think> tags from reasoning models (qwen)
    let content=msg&&msg.content;
    if(content&&content.includes('<think>'))content=content.replace(/<think>[\s\S]*?<\/think>\s*/g,'').trim();
    return{reply:content,message:msg,provider:'groq/'+model.split('/').pop(),usage:j.usage};
  }
  throw new Error(lastErr||'All Groq models failed');
}

// Simple response cache (LRU, 200 entries, 10 min TTL)
const _aiCache=new Map();const _AI_CACHE_MAX=200;const _AI_CACHE_TTL=600000;
function _aiCacheKey(msgs){return msgs.slice(-3).map(m=>m.content||'').join('|').slice(0,300)}
function _aiCacheGet(key){const e=_aiCache.get(key);if(!e)return null;if(Date.now()-e.ts>_AI_CACHE_TTL){_aiCache.delete(key);return null}return e.reply}
function _aiCacheSet(key,reply){if(_aiCache.size>=_AI_CACHE_MAX){const first=_aiCache.keys().next().value;_aiCache.delete(first)}_aiCache.set(key,{reply,ts:Date.now()})}

const COACH_SYSTEM=`You are an expert Business English coach speaking with a fluent professional who wants to sound MORE polished and use more sophisticated vocabulary in business contexts.

When they say something, structure your reply in this exact short format:

1. Brief acknowledgment of what they said (one sentence)
2. A more polished/business-appropriate rewrite of their last sentence
3. ONE vocabulary or idiom tip relevant to it (a sophisticated word/phrase + meaning + how to use it)
4. A follow-up question that pushes the conversation forward

Keep total response under 90 words. Use sophisticated vocabulary yourself naturally — words like "leverage", "nuance", "cadence", "granular", "alignment", "downstream", "actionable", "stakeholder", "throughput", "paradigm", "by and large", "in lieu of", "tantamount to", "circle back", "drill down".

Be warm but direct. Never explain that you are an AI.`;

// v20: Notes' voice recorder (app/voicenote.js): /api/transcribe is Bro's hearing, /api/notes/translate (modules/notes.js)
try{require('./modules/notes.js').install(app,{auth})}catch(e){console.log('[notes] off:',e.message)}

app.post('/api/coach/chat',auth,async(req,res)=>{
  if(!groqKey()&&!geminiKey())return res.status(503).json({error:'AI coach not configured.'});
  const messages=Array.isArray(req.body&&req.body.messages)?req.body.messages.slice(-20):null;
  if(!messages||!messages.length)return res.status(400).json({error:'messages required'});
  const sys=req.body.system||COACH_SYSTEM;
  const apiMsgs=[{role:'system',content:sys},...messages.map(m=>({role:m.role==='assistant'?'assistant':'user',content:String(m.content||'').slice(0,4000)}))];
  try{
    let reply='';
    if(geminiKey()){try{const g=await _callGemini(apiMsgs,{maxTokens:600,systemPrompt:sys});reply=g.reply}catch(e){}}
    if(!reply&&groqKey()){try{const g=await _callGroq(apiMsgs,{maxTokens:600});reply=g.reply}catch(e){}}
    if(!reply)return res.status(502).json({error:'Coach is busy — try again in a moment.'});
    res.json({reply});
  }catch(e){res.status(500).json({error:String(e.message||e)})}
});

// ═══ BRO / BRI — Life Coach Chat (Groq free tier → Anthropic fallback) ═══
// ─── Bro agent tools ─────────────────────────────────────────────
const BRO_TOOLS=[
  {name:'create_calendar_event',description:'Add an event to the user\'s calendar: a meeting, class, appointment, birthday, anything on a date (and at a time). It is saved in Brodoit\'s calendar, and in their Google Calendar too when they connected it. Use exactly the title, date and time they asked for.',input_schema:{type:'object',properties:{title:{type:'string',description:'Event title'},date:{type:'string',description:'Date in YYYY-MM-DD format'},time:{type:'string',description:'Start time in HH:MM 24h format (leave out for an all-day event)'},duration:{type:'integer',description:'Duration in minutes (default 60)'},notes:{type:'string',description:'Optional description'}},required:['title','date']}},
  {name:'create_task',description:'Create a task in Brodoit for the user. Use when they ask to add a task, reminder, todo, etc.',input_schema:{type:'object',properties:{title:{type:'string',description:'Task title'},priority:{type:'string',enum:['low','medium','high'],description:'Priority level'},due_date:{type:'string',description:'Due date YYYY-MM-DD (optional)'},notes:{type:'string',description:'Optional notes'},board:{type:'string',enum:['home','office'],description:'Board (default home)'}},required:['title']}},
  {name:'get_todays_schedule',description:'Get the user\'s calendar events and tasks for today or a specific date. Use when they ask "what\'s on my schedule", "plan my day", "what do I have today", etc.',input_schema:{type:'object',properties:{date:{type:'string',description:'Date YYYY-MM-DD (defaults to today)'}}}},
  {name:'complete_task',description:'Mark a task as done. Use when the user says they finished something.',input_schema:{type:'object',properties:{title:{type:'string',description:'Task title or partial match to find it'}},required:['title']}},
  {name:'create_schedule_block',description:'Create a time block on the user\'s day schedule. Use for time-blocking, focus sessions, etc.',input_schema:{type:'object',properties:{date:{type:'string',description:'Date YYYY-MM-DD (defaults to today)'},start_time:{type:'string',description:'Start HH:MM 24h'},end_time:{type:'string',description:'End HH:MM 24h'},label:{type:'string',description:'Block label'}},required:['start_time','end_time','label']}},
  {name:'set_reminder',description:'Set a reminder that will send a push notification at a specific time. Use when user says "remind me", "set alarm", "notify me at", etc.',input_schema:{type:'object',properties:{title:{type:'string',description:'What to remind about'},date:{type:'string',description:'Date YYYY-MM-DD (defaults to today)'},time:{type:'string',description:'Time in HH:MM 24h format'},notes:{type:'string',description:'Optional extra details'}},required:['title','time']}}
];
// v23: Bro's dates and times: "9:30", "09:30", "9:30 pm", "21.30" → "21:30"; YYYY-MM-DD only
function _hhmm(t){const m=/^\s*(\d{1,2})(?:[:.](\d{2}))?\s*([ap])\.?\s*m?\.?\s*$/i.exec(String(t||''))||/^\s*(\d{1,2})[:.](\d{2})\s*$/.exec(String(t||''));if(!m)return '';let h=+m[1];const mi=+(m[2]||0);if(m[3]){const pm=/p/i.test(m[3]);if(h<1||h>12)return '';h=h%12+(pm?12:0)}if(h>23||mi>59)return '';return String(h).padStart(2,'0')+':'+String(mi).padStart(2,'0')}
function _isDayStr(d){return/^\d{4}-\d{2}-\d{2}$/.test(String(d||''))&&new Date(d+'T00:00:00Z').toISOString().slice(0,10)===d}
function _addMins(t,n){const[h,m]=t.split(':').map(Number);const x=Math.min(23*60+59,h*60+m+n);return String(Math.floor(x/60)).padStart(2,'0')+':'+String(x%60).padStart(2,'0')}
async function _broExecTool(toolName,input,userPhone,userTz){
  const _tzT=userTz||_getUserTz(userPhone);const today=dayKey(new Date(),_tzT&&_tzT!=='UTC'?_tzT:'Asia/Kolkata'); // v21: the user's own date
  if(toolName==='create_calendar_event'){
    // v23: always saved in Brodoit's calendar (an event at a time is a block on that day's plan; an all-day one a task on
    // that date), and in Google Calendar too when it is connected. Before, without Google the event was simply lost.
    const title=String(input.title||'').replace(/\s+/g,' ').trim().slice(0,100),date=String(input.date||today).trim();
    if(!title)return{ok:false,error:'title required'};
    if(!_isDayStr(date))return{ok:false,error:'date must be YYYY-MM-DD'};
    const tz=userTz||_getUserTz(userPhone),google=!!db.prepare('SELECT 1 FROM google_tokens WHERE user_phone=?').get(userPhone);
    if(input.time){
      const st=_hhmm(input.time);if(!st)return{ok:false,error:'time must be HH:MM, 24-hour'};
      const et=_addMins(st,Math.max(5,Math.min(720,parseInt(input.duration,10)||60)));
      const dup=db.prepare('SELECT * FROM schedule_blocks WHERE user_phone=? AND date=? AND start_time=? AND lower(label)=lower(?)').get(userPhone,date,st,title);
      if(dup)return{ok:true,already:true,event:{id:dup.id,title,date,time:st,end:dup.end_time,in_brodoit:true,synced_to_google:!!dup.gcal_event_id}};
      const id=_crypto.randomBytes(8).toString('hex');
      const gcal=await _gcalCreateTimed(userPhone,date,st,et,title,'',tz,{event:true,notes:input.notes});
      db.prepare('INSERT INTO schedule_blocks(id,user_phone,date,start_time,end_time,label,color,gcal_event_id,gcal_email)VALUES(?,?,?,?,?,?,?,?,?)').run(id,userPhone,date,st,et,title,'#2F6FDE',gcal?.id||null,gcal?.email||null);
      return{ok:true,event:{id,title,date,time:st,end:et,in_brodoit:true,synced_to_google:!!gcal,google_link:gcal&&gcal.link||undefined},note:gcal?undefined:google?'Saved in Brodoit. Google Calendar did not take it just now.':'Saved in Brodoit\'s calendar (Google Calendar is not connected).'};
    }
    const dupT=db.prepare("SELECT id FROM tasks WHERE user_phone=? AND due_date=? AND lower(title)=lower(?) AND status!='done'").get(userPhone,date,title);
    if(dupT)return{ok:true,already:true,event:{id:dupT.id,title,date,all_day:true,in_brodoit:true}};
    const id=genId();
    db.prepare('INSERT INTO tasks(id,user_phone,title,notes,priority,status,due_date,reminder_time,source,board)VALUES(?,?,?,?,?,?,?,?,?,?)').run(id,userPhone,title,String(input.notes||''),'medium','pending',date,'','bro-event','home');
    let gcal=null;const ga=google?await gAccessToken(userPhone):null;
    if(ga){try{const end=new Date(Date.parse(date+'T00:00:00Z')+864e5).toISOString().slice(0,10); // all-day: the end date is the day after
      const r=await fetch('https://www.googleapis.com/calendar/v3/calendars/primary/events',{method:'POST',headers:{Authorization:'Bearer '+ga.token,'Content-Type':'application/json'},body:JSON.stringify({summary:title,description:String(input.notes||'Added by Bro in Brodoit'),start:{date},end:{date:end}})});
      const j=await r.json();if(!j.error)gcal={id:j.id,link:j.htmlLink}}catch(e){gcal=null}}
    return{ok:true,event:{id,title,date,all_day:true,in_brodoit:true,synced_to_google:!!gcal,google_link:gcal&&gcal.link||undefined},note:gcal?undefined:google?'Saved in Brodoit. Google Calendar did not take it just now.':'Saved in Brodoit\'s calendar (Google Calendar is not connected).'};
  }
  if(toolName==='create_task'){
    const id=genId();const b=input.board||'home';
    db.prepare('INSERT INTO tasks(id,user_phone,title,notes,priority,status,due_date,reminder_time,source,board)VALUES(?,?,?,?,?,?,?,?,?,?)').run(id,userPhone,input.title.trim(),input.notes||'',input.priority||'medium','pending',input.due_date||'','','bro',b);
    const row=db.prepare('SELECT * FROM tasks WHERE id=?').get(id);
    return{ok:true,task:row};
  }
  if(toolName==='get_todays_schedule'){
    const d=input.date||today;
    const tasks=db.prepare('SELECT id,title,status,priority,due_date,board FROM tasks WHERE user_phone=? AND (due_date=? OR due_date=\'\') AND status!=\'done\' ORDER BY priority DESC').all(userPhone,d);
    const blocks=db.prepare('SELECT label,start_time,end_time FROM schedule_blocks WHERE user_phone=? AND date=? ORDER BY start_time ASC').all(userPhone,d);
    let events=[];
    const ga=await gAccessToken(userPhone);
    if(ga){try{const schTz=_tzT&&_tzT!=='UTC'?_tzT:'Asia/Kolkata';const from=d+'T00:00:00';const to=d+'T23:59:59';const r=await fetch('https://www.googleapis.com/calendar/v3/calendars/primary/events?timeMin='+encodeURIComponent(from)+'&timeMax='+encodeURIComponent(to)+'&timeZone='+encodeURIComponent(schTz)+'&singleEvents=true&orderBy=startTime&maxResults=50',{headers:{Authorization:'Bearer '+ga.token}});const j=await r.json();events=(j.items||[]).map(e=>({title:e.summary,start:e.start?.dateTime||e.start?.date,end:e.end?.dateTime||e.end?.date}))}catch(e){}}
    return{ok:true,date:d,tasks,blocks,calendar_events:events};
  }
  if(toolName==='complete_task'){
    const q='%'+input.title.trim()+'%';
    const t=db.prepare("SELECT * FROM tasks WHERE user_phone=? AND status!='done' AND title LIKE ? ORDER BY created_at DESC LIMIT 1").get(userPhone,q);
    if(!t)return{ok:false,error:'No pending task found matching "'+input.title+'"'};
    db.prepare("UPDATE tasks SET status='done',updated_at=datetime('now') WHERE id=?").run(t.id);
    return{ok:true,task:{id:t.id,title:t.title,status:'done'}};
  }
  if(toolName==='create_schedule_block'){
    const d=String(input.date||today).trim(),st=_hhmm(input.start_time),et=_hhmm(input.end_time),label=String(input.label||'').replace(/\s+/g,' ').trim().slice(0,100);
    if(!_isDayStr(d))return{ok:false,error:'date must be YYYY-MM-DD'};
    if(!st||!et)return{ok:false,error:'start_time and end_time must be HH:MM, 24-hour'};
    if(et<=st)return{ok:false,error:'end_time must be after start_time'};
    if(!label)return{ok:false,error:'label required'};
    const dup=db.prepare('SELECT * FROM schedule_blocks WHERE user_phone=? AND date=? AND start_time=? AND lower(label)=lower(?)').get(userPhone,d,st,label);
    if(dup)return{ok:true,already:true,block:{id:dup.id,label,start:st,end:dup.end_time,date:d,synced_to_gcal:!!dup.gcal_event_id}};
    const id=_crypto.randomBytes(8).toString('hex');
    const gcal=await _gcalCreateTimed(userPhone,d,st,et,label,'',userTz);
    db.prepare('INSERT INTO schedule_blocks(id,user_phone,date,start_time,end_time,label,color,gcal_event_id,gcal_email)VALUES(?,?,?,?,?,?,?,?,?)').run(id,userPhone,d,st,et,label,'#1F1E1C',gcal?.id||null,gcal?.email||null);
    return{ok:true,block:{id,label,start:st,end:et,date:d,synced_to_gcal:!!gcal}};
  }
  if(toolName==='set_reminder'){
    const id=genId(),d=String(input.date||today).trim(),t=_hhmm(input.time); // v23: the user's own date (was the server's UTC date)
    if(!_isDayStr(d))return{ok:false,error:'date must be YYYY-MM-DD'};
    if(!t)return{ok:false,error:'time must be HH:MM, 24-hour'};
    const title=(input.title||'Reminder').trim();
    db.prepare('INSERT INTO tasks(id,user_phone,title,notes,priority,status,due_date,reminder_time,source,board)VALUES(?,?,?,?,?,?,?,?,?,?)').run(id,userPhone,title,input.notes||'','medium','pending',d,t,'bro-reminder','home');
    return{ok:true,reminder:{id,title,date:d,time:t,message:"Reminder set! You'll get a notification at "+t}};
  }
  return{ok:false,error:'Unknown tool'};
}

// v16: Bro chat bills Bro Core's brain, so each user gets 30 messages a minute
const _broChatHits=new Map();
function _broChatLimited(phone){const now=Date.now(),l=(_broChatHits.get(phone)||[]).filter(t=>now-t<60000);l.push(now);_broChatHits.set(phone,l);if(_broChatHits.size>5000)_broChatHits.clear();return l.length>30}
app.post('/api/bro/chat',auth,async(req,res)=>{
  if(_broChatLimited(req.user&&req.user.phone||req.ip))return res.status(429).json({error:'Slow down a little and try again in a minute.'});
  if(!groqKey()&&!geminiKey()&&!(global._elevenBrain&&global._elevenBrain.available()))return res.status(503).json({error:'Chat not configured (no AI keys set).'});
  const messages=Array.isArray(req.body&&req.body.messages)?req.body.messages.slice(-10):null;
  if(!messages||!messages.length)return res.status(400).json({error:'messages required'});
  const imageB64=req.body.image||null;
  const imageMime=req.body.imageMime||'image/jpeg';
  const agent=(req.body.agent==='bri')?'bri':'bro';
  const mode=req.body.mode||'ask';
  const today=new Date().toISOString().slice(0,10);
  const dayName=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][new Date().getDay()];
  const sysFriend='You are the user\'s closest friend — not an assistant, a FRIEND. You\'re their ride-or-die bestie who genuinely cares. Talk like a real close friend texts: short messages, casual, use emojis naturally, be playful and supportive. Ask follow-up questions about their life. If they\'re feeling down, listen and hype them up. If they\'re happy, celebrate. Tease lovingly, roast gently when they need motivation. Keep it real. You\'re their person.\n\nSTYLE RULES (STRICT):\n- Write like a TEXT MESSAGE, not a blog post. NO markdown headers (##), NO bold (**), NO bullet lists, NO numbered lists. Just plain conversational text.\n- Keep messages short (1-3 sentences usually, longer for real talk moments).\n- Never use technical jargon, fancy words, or formal language. Talk like a 20-something friend.\n- Never say you\'re an AI, language model, or assistant.\n- End with a question or check-in to keep the conversation going.\n- LANGUAGE: If the user writes in Hindi or Hinglish, reply in the same language naturally. Mix Hindi/English casually.\nToday is '+dayName+', '+today+'.';
  const sysAsk='You are Bro — the user\'s smart best friend who lives inside the Brodoit app. You talk like a real person: casual, warm, and direct. Today is '+dayName+', '+today+'. You have tools to create calendar events, add tasks, check schedules, complete tasks, and create time blocks. Only use tools when the user EXPLICITLY asks to create/add/schedule something. Do NOT create tasks on your own.\n\nSTYLE RULES (STRICT):\n- Talk like a smart friend, NOT a textbook or blog. Keep language simple and natural.\n- For casual questions (jokes, opinions, chatting): reply conversationally in plain text. NO headers, NO bold, NO formatting. Just talk normally.\n- For serious/complex questions (homework, coding, explanations): use markdown formatting (bold, bullet points, code blocks) ONLY when it genuinely helps readability.\n- NEVER use markdown headers (##) — they look robotic in chat.\n- NEVER end with "Need help with anything else?", "Want me to explain more?" or similar. Just answer and stop.\n- NEVER ask clarifying questions unless truly ambiguous.\n- Never say you\'re an AI or language model — you\'re Bro.\n- Avoid unnecessary technical jargon. Explain things simply unless the user is asking about a technical topic.\n- LANGUAGE: If the user writes in Hindi or Hinglish, reply in the same language. Mix Hindi/English naturally.\n- IMAGE ANALYSIS: If the user sends an image, describe/analyze it based on their question.';
  const sys=mode==='friend'?sysFriend:sysAsk;
  const mapped=messages.map(m=>({role:m.role==='assistant'?'assistant':'user',content:String(m.content||'').slice(0,3000)}));
  // Attach image to the last user message if provided
  if(imageB64&&mapped.length){mapped[mapped.length-1].image={data:imageB64,mime:imageMime}}
  const groqTools=groqKey()?BRO_TOOLS.map(t=>({type:'function',function:{name:t.name,description:t.description,parameters:t.input_schema}})):undefined;
  // Detect if user's message likely needs tools (task/calendar actions)
  const lastMsg=String((mapped[mapped.length-1]&&mapped[mapped.length-1].content)||'').toLowerCase();
  const needsTools=mode==='ask'&&groqKey()&&/\b(add|create|schedule|remind|task|event|block|calendar|complete|done|finish|mark)\b/i.test(lastMsg);
  // v16 Bro Core: a crisis message gets the scripted helpline reply (no model involved) before anything else
  const _B=global._broCore;
  const _sc=_B&&_B.safety.check(String((mapped[mapped.length-1]&&mapped[mapped.length-1].content)||''));
  if(_sc){_broSaveMsg(req.user.phone,'user',mapped[mapped.length-1].content);_broSaveMsg(req.user.phone,'assistant',_sc.reply);return res.json({reply:_sc.reply,provider:'safety'})}

  // Check cache first
  const cacheKey=_aiCacheKey(mapped);
  const cached=_aiCacheGet(cacheKey);
  if(cached)return res.json({reply:cached,cached:true});

  // Estimate max tokens based on input length
  const inputLen=mapped.reduce((s,m)=>s+(m.content?m.content.length:0),0);
  const maxTok=inputLen>3000?8192:inputLen>1500?4096:2048;

  try{
    let apiMsgs=[{role:'system',content:sys},...mapped];
    let actions=[];

    // If user explicitly needs tools (task/calendar actions), use Groq with tools
    // Skip tools path if image is attached — Groq doesn't support vision
    if(needsTools&&!imageB64){try{
      for(let loop=0;loop<4;loop++){
        const groqResult=await _callGroq(apiMsgs,{maxTokens:maxTok,tools:groqTools});
        const msg=groqResult.message;
        if(msg&&msg.tool_calls&&msg.tool_calls.length){
          apiMsgs.push(msg);
          for(const tc of msg.tool_calls){
            const args=typeof tc.function.arguments==='string'?JSON.parse(tc.function.arguments):tc.function.arguments;
            const result=await _broExecTool(tc.function.name,args,req.user.phone,req.user.tz||_getUserTz(req.user.phone));
            actions.push({tool:tc.function.name,input:args,result});
            apiMsgs.push({role:'tool',tool_call_id:tc.id,content:JSON.stringify(result)});
          }
          continue;
        }
        const reply=(msg&&msg.content)||'';
        _aiCacheSet(cacheKey,reply);
        const uc=mapped[mapped.length-1]&&mapped[mapped.length-1].content||'';
        _broSaveMsg(req.user.phone,'user',uc);
        _broSaveMsg(req.user.phone,'assistant',reply);
        return res.json({reply,provider:'groq',actions:actions.length?actions:undefined});
      }
      return res.json({reply:'I tried to help but hit a loop — try rephrasing.',actions:actions.length?actions:undefined});
    }catch(toolErr){console.log('[bro] Tool path error:',toolErr.message)}}

    // Provider strategy: Gemini first (1500 req/day free) → Groq fallback (tight token limits)
    // This maximizes daily throughput — Groq reserved mainly for tool-calling
    let reply='',provider='';
    let lastError='';
    let draftReply='',draftProvider='';
    // v16 Step 0: Bro Core — the open-model brain plus Bro's memory, lessons and today's knowledge (its emergency
    // fallback is the old Gemini → ElevenLabs chain). Steps 1-2 below then run only for photos or without Bro Core.
    if(!draftReply&&_B&&!imageB64){
      try{
        const cx=await _B.context(req.user,String((mapped[mapped.length-1]&&mapped[mapped.length-1].content)||''),{mode:'text'});
        const g=await _B.chat({system:sys+'\n\n'+cx.system,messages:mapped,maxTokens:maxTok,purpose:'bro'});
        draftReply=g.text;draftProvider=_broProvider(g);
      }catch(e){lastError='Bro Core: '+e.message;console.log('[bro] Bro Core failed:',e.message)}
    }
    // Step 1: Try Gemini first (generous free tier: 1500 req/day, 1M tokens/min)
    if(!draftReply&&(!_B||imageB64)&&(geminiKey()||(global._elevenBrain&&global._elevenBrain.available()))){
      try{
        const g=await _callGemini(apiMsgs,{maxTokens:maxTok,systemPrompt:sys});
        draftReply=g.reply;draftProvider='gemini';
      }catch(e){lastError='Gemini: '+e.message;console.log('[bro] Gemini failed:',e.message)}
    }
    // Step 2: Groq fallback (auto-rotates models on rate limit)
    if(!draftReply&&!_B&&groqKey()&&!imageB64){
      try{
        const groqMsgs=apiMsgs.slice(0,1).concat(apiMsgs.slice(-6).map(m=>({...m,content:String(m.content||'').slice(0,2000)})));
        const g=await _callGroq(groqMsgs,{maxTokens:Math.min(maxTok,2048)});
        draftReply=g.reply;draftProvider=g.provider||'groq';
      }catch(e){lastError='Groq: '+e.message;console.log('[bro] Groq failed:',e.message)}
    }
    if(!draftReply){console.log('[bro] All providers failed:',lastError);return res.status(502).json({error:'Bro is taking a quick break — try again in a moment.'})}
    // Step 2: Verify/improve with the other model (skip for friend mode — keep it fast)
    // v13: no second 'verify' pass — it doubled every reply's wait; one good model answers directly.
    const verifyModel=null;
    if(verifyModel&&draftReply.length>40){
      try{
        const verifySys='You are a quality checker. You receive a draft response to a user question. Your job: check for factual errors, missing info, or unclear answers. If the draft is good, return it as-is. If it has issues, return an improved version. Keep the same tone and style. Do NOT add meta-commentary like "Here is the improved version" — just output the final answer directly. Do NOT add trailing questions like "Need anything else?" — just answer and stop.';
        const verifyMsgs=[{role:'system',content:verifySys},{role:'user',content:'User asked: '+String(mapped[mapped.length-1]?.content||'').slice(0,1000)+'\n\nDraft response:\n'+draftReply.slice(0,3000)+'\n\nReturn the verified/improved response:'}];
        if(verifyModel==='groq'){
          const vr=await _callGroq(verifyMsgs,{maxTokens:Math.min(maxTok,2048)});
          if(vr.reply&&vr.reply.length>20){reply=vr.reply;provider='dual (gemini+groq)'}
        }else{
          const vr=await _callGemini(verifyMsgs,{maxTokens:maxTok,systemPrompt:verifySys});
          if(vr.reply&&vr.reply.length>20){reply=vr.reply;provider='dual (groq+gemini)'}
        }
      }catch(e){console.log('[bro] Verify step failed:',e.message)}
    }
    if(!reply){reply=draftReply;provider=draftProvider}
    _aiCacheSet(cacheKey,reply);
    // Save to persistent memory
    const userContent=mapped[mapped.length-1]&&mapped[mapped.length-1].content||'';
    _broSaveMsg(req.user.phone,'user',userContent);
    _broSaveMsg(req.user.phone,'assistant',reply);
    return res.json({reply,provider,actions:actions.length?actions:undefined});
  }catch(e){console.log('[bro] Exception:',e.message);return res.status(500).json({error:'Connection issue — please try again.'})}
});


