// v21: Bro's library (modules/brolibrary.js): the breathing cues, affirmations and guided meditations recorded once in
// Bro's one voice; created once Bro Core is up (below). The routes serve its file first.
let _broLib = null;
let _bookVoice = null; // v31 studio narration of the book notes (modules/bookvoice.js)
const BREATHE_CUES = { 'breathe-in': 'Breathe in.', 'breathe-out': 'Breathe out.', 'breathe-hold': 'Hold.', 'breathe-done': 'Session complete. Well done.' };
// v23: book summaries in Bro's voice. A summary is recorded the first time someone plays it (all 106 at once would be
// hours of CPU and ~700 MB); until then the page reads it live in Bro's voice. The texts are the page's own
// (BOOK_SUMMARIES in the SPA, read once from the built HTML) and the Hindi ones from books-hi/<id>.json.
let _booksCache = null;
function _bookText(id) {
  id = String(id || '');
  // v32: the whole book, chapter by chapter, for the public-domain books (app/briefs/<id>.json)
  if (id.startsWith('brief-')) {
    const base = id.slice(6).replace(/[^a-zA-Z0-9_-]/g, '');
    try { const j = JSON.parse(_fs.readFileSync(_path.join(__dirname, 'app', 'briefs', base + '.json'), 'utf8')); if (j && j.text) return { title: j.title || '', text: String(j.text), lang: 'en' }; } catch (e) { /* not a public-domain book */ }
    return null;
  }
  if (id.startsWith('hi-')) {
    const base = id.slice(3).replace(/[^a-zA-Z0-9_-]/g, '');
    // v27: only Hindi versions of Bro's book notes (notes: 2); a translation of a pre-v27 brief is never used
    try { const j = JSON.parse(_fs.readFileSync(_path.join(MEDIA_DIR, 'books-hi', base + '.json'), 'utf8')); if (j && j.notes === 2 && j.summary) return { title: j.title || '', text: String(j.summary).replace(/\\/g, ''), lang: 'hi' }; } catch (e) { /* none yet */ }
    return null;
  }
  if (!_booksCache) {
    _booksCache = new Map();
    try {
      const m = /const BOOK_SUMMARIES=(\[[\s\S]*?\n\]);/.exec(HTML);
      const arr = m ? require('vm').runInNewContext('(' + m[1] + ')', {}, { timeout: 2000 }) : [];
      for (const b of arr) if (b && b.id && b.summary) _booksCache.set(String(b.id), { title: String(b.title || ''), text: String(b.summary).replace(/\\/g, ''), lang: 'en', book: b });
    } catch (e) { console.log('[books] could not read the summaries:', e.message); }
  }
  return _booksCache.get(id) || null;
}
const _bookWant = new Set();
const _bookWantFile = () => _path.join(MEDIA_DIR, 'bro-voice', 'books-wanted.json');
try { for (const k of JSON.parse(_fs.readFileSync(_bookWantFile(), 'utf8'))) if (typeof k === 'string') _bookWant.add(k); } catch (e) { /* none yet */ }
function _wantBook(id) {
  if (_bookWant.has(id) || !_bookText(id)) return;
  _bookWant.add(id);
  try { _fs.mkdirSync(_path.dirname(_bookWantFile()), { recursive: true }); _fs.writeFileSync(_bookWantFile(), JSON.stringify([..._bookWant].slice(-400))); } catch (e) { /* kept in memory */ }
  clearTimeout(_wantBook.t); _wantBook.t = setTimeout(() => { try { if (_broLib) _broLib.run().catch(() => {}); } catch (e) {} }, 5000); if (_wantBook.t.unref) _wantBook.t.unref();
}
// v27: Bro's book notes (his own short notes on each book's ideas, ~3 minutes) are all recorded ahead of time, the ones
// people asked for first; Hindi ones when someone plays them. Keys are "note-<id>": the "book-<id>" recordings were of
// the pre-v27 chapter-by-chapter briefs and are deleted at start (below).
function _allBookIds() { _bookText(''); return [..._booksCache.keys()]; }
function broLibraryItems() {
  const out = Object.entries(BREATHE_CUES).map(([key, text]) => ({ key, text, speed: 0.9 }));
  const ids = [..._bookWant, ..._allBookIds().filter(id => !_bookWant.has(id))];
  // v31: a note the studio narration already reads is not recorded again in Bro's voice (saves the CPU for live calls)
  for (const id of ids) { const b = _bookText(id); if (b && !(_bookVoice && _bookVoice.file(id))) out.push({ key: 'note-' + id, text: b.text, lang: b.lang, speed: 0.97, gapMs: 800, breathMs: 400 }); }
  for (const [key, e] of Object.entries(AUDIO_LIBRARY)) if (e.script && ['affirmation', 'guided', 'vipassana'].includes(e.kind)) out.push({ key, text: e.script, speed: e.kind === 'affirmation' ? 0.94 : 0.9, gapMs: e.kind === 'affirmation' ? 1400 : 2200, breathMs: 1000 });
  return out;
}

// Used by <audio src> for affirmations + guided meditations (static MP3s).

app.get('/api/audio/:id', async (req, res) => {
  const token = String(req.query.token || req.headers['x-token'] || '').trim();
  const u = token ? db.prepare('SELECT * FROM users WHERE token=?').get(token) : null;
  if (!u) return res.status(401).json({ error: 'unauthorized' });
  const id = String(req.params.id || '').replace(/[^a-zA-Z0-9_-]/g, '');
  const entry = AUDIO_LIBRARY[id];
  if (!entry) return res.status(404).json({ error: 'unknown audio id' });
  // v27: a bundled file with no script has no known source or licence: not served until it is traced
  if (!entry.script && process.env.UNTRACED_AUDIO !== '1') return res.status(404).json({ error: 'unavailable' });

  // v21: Bro's own recording (modules/brolibrary.js, his one voice) once it exists; until then the bundled file
  const bro = _broLib && _broLib.file(id);
  if (bro && require('./modules/brolibrary.js').sendAudio(req, res, bro, 'no-cache')) return;
  // 1) Check for pre-baked static MP3 (bundled in repo — zero API cost)
  const staticPath = _path.join(__dirname, 'audio-static', id + '.mp3');
  try {
    if (_fs.existsSync(staticPath)) {
      const stat = _fs.statSync(staticPath);
      const total = stat.size;
      // Handle Range requests (required for iOS Safari audio playback)
      const range = req.headers.range;
      if (range) {
        const parts = range.replace(/bytes=/, '').split('-');
        const start = parseInt(parts[0], 10);
        const end = parts[1] ? parseInt(parts[1], 10) : total - 1;
        const chunkSize = end - start + 1;
        res.writeHead(206, {
          'Content-Range': 'bytes ' + start + '-' + end + '/' + total,
          'Accept-Ranges': 'bytes',
          'Content-Length': String(chunkSize),
          'Content-Type': 'audio/mpeg',
          'Cache-Control': 'public, max-age=604800',
          'X-Tts-Source': 'static',
        });
        return _fs.createReadStream(staticPath, { start, end }).pipe(res);
      }
      res.set('Content-Type', 'audio/mpeg');
      res.set('Cache-Control', 'public, max-age=604800');
      res.set('X-Tts-Source', 'static');
      res.set('Content-Length', String(total));
      res.set('Accept-Ranges', 'bytes');
      return _fs.createReadStream(staticPath).pipe(res);
    }
  } catch (e) {}

  // No static file — tell client to use browser TTS fallback
  return res.status(404).json({ error: 'audio not found — use browser TTS' });
});

// GET /api/audio-library — small JSON manifest the client uses to render cards.
app.get('/api/audio-library', auth, (req, res) => {
  const items = Object.entries(AUDIO_LIBRARY).map(([id, e]) => ({
    id, title: e.title, desc: e.desc, mins: e.mins, color: e.color, kind: e.kind,
  }));
  res.json({ items });
});

// GET /api/audio-script/:id — returns the script text so the client can
// fall back to browser speechSynthesis if the static MP3 fails to load.
app.get('/api/audio-script/:id', (req, res) => {
  const id = String(req.params.id || '').replace(/[^a-zA-Z0-9_-]/g, '');
  const entry = AUDIO_LIBRARY[id];
  if (!entry) return res.status(404).json({ error: 'unknown audio id' });
  res.json({ id, title: entry.title, script: entry.script, kind: entry.kind, mins: entry.mins });
});

app.get('/api/book-audio/:id', (req, res) => {
  // Auth: accept token from query string (needed for <audio src=...> on iOS),
  // x-token header, or tf_token cookie
  const t = String(req.query.token||'').trim() || req.headers['x-token'] ||
    (()=>{try{const c=(req.headers.cookie||'');const m=c.match(/tf_token=([^;]+)/);return m?decodeURIComponent(m[1]):''}catch(e){return ''}})();
  if(!t)return res.status(401).json({error:'Login required'});
  const u=db.prepare('SELECT * FROM users WHERE token=?').get(t);
  if(!u)return res.status(401).json({error:'Invalid token'});

  const id = String(req.params.id || '').replace(/[^a-zA-Z0-9_-]/g, '');
  // v23: one voice. Bro's recording of the summary when it exists; otherwise 404 (the page reads it live in Bro's voice)
  // and the recording is queued. The old narrators (edge-tts English, ElevenLabs Hindi) are no longer played; BOOKS_OLD_AUDIO=1 brings them back.
  // v31: the studio narration (modules/bookvoice.js: an openly licensed voice model, recorded in CI) comes first
  const pv = _bookVoice && _bookVoice.file(id);
  if (pv && require('./modules/brolibrary.js').sendAudio(req, res, pv, 'no-cache')) return;
  const bro = _broLib && _broLib.file('note-' + id);
  if (bro && require('./modules/brolibrary.js').sendAudio(req, res, bro, 'no-cache')) return;
  if (process.env.BOOKS_OLD_AUDIO !== '1') { if (!id.startsWith('brief-')) _wantBook(id); return res.status(404).json({ error: 'not recorded in Bro\'s voice yet', live: true }); }
  let staticPath = _path.join(__dirname, 'audio-static', id + '.mp3');
  if (id.startsWith('hi-')) { const m = _path.join(MEDIA_DIR, 'books-hi', id + '.mp3'); if (_fs.existsSync(m)) staticPath = m; }
  try {
    if (_fs.existsSync(staticPath)) {
      const stat = _fs.statSync(staticPath);
      if (stat.size > 0) {
        const total = stat.size;
        // Handle Range requests (required for iOS Safari audio playback)
        const range = req.headers.range;
        if (range) {
          const parts = range.replace(/bytes=/, '').split('-');
          const start = parseInt(parts[0], 10);
          const end = parts[1] ? parseInt(parts[1], 10) : total - 1;
          const chunkSize = end - start + 1;
          res.writeHead(206, {
            'Content-Range': 'bytes ' + start + '-' + end + '/' + total,
            'Accept-Ranges': 'bytes',
            'Content-Length': String(chunkSize),
            'Content-Type': 'audio/mpeg',
            'Cache-Control': 'public, max-age=604800',
          });
          return _fs.createReadStream(staticPath, { start, end }).pipe(res);
        }
        res.set('Content-Type', 'audio/mpeg');
        res.set('Cache-Control', 'public, max-age=604800');
        res.set('Content-Length', String(total));
        res.set('Accept-Ranges', 'bytes');
        return _fs.createReadStream(staticPath).pipe(res);
      }
    }
  } catch (e) {}
  res.status(404).json({ error: 'no static audio' });
});

// Motivational video clips. v27: described only as "CC-licensed YouTube clips", with no record of which clip or licence,
// so they are not served (and the app hides them) unless MV_VIDEOS=1, once each one's source is traced.
app.get('/api/mv-video/:clip', (req, res) => {
  if (process.env.MV_VIDEOS !== '1') return res.status(404).json({ error: 'unavailable' });
  const clip = String(req.params.clip || '').replace(/[^a-zA-Z0-9_-]/g, '');
  if (!clip) return res.status(400).json({ error: 'missing clip' });
  const filePath = _path.join(__dirname, 'video-mv', clip + '.mp4');
  try {
    if (!_fs.existsSync(filePath)) return res.status(404).json({ error: 'not found' });
    const stat = _fs.statSync(filePath);
    const total = stat.size;
    const range = req.headers.range;
    if (range) {
      const parts = range.replace(/bytes=/, '').split('-');
      const start = parseInt(parts[0], 10);
      const end = parts[1] ? parseInt(parts[1], 10) : total - 1;
      res.writeHead(206, {
        'Content-Range': 'bytes ' + start + '-' + end + '/' + total,
        'Accept-Ranges': 'bytes',
        'Content-Length': String(end - start + 1),
        'Content-Type': 'video/mp4',
        'Cache-Control': 'public, max-age=604800',
      });
      return _fs.createReadStream(filePath, { start, end }).pipe(res);
    }
    res.set({ 'Content-Type': 'video/mp4', 'Cache-Control': 'public, max-age=604800', 'Content-Length': String(total), 'Accept-Ranges': 'bytes' });
    return _fs.createReadStream(filePath).pipe(res);
  } catch (e) { res.status(500).json({ error: 'read error' }); }
});

