let newsLastFullRefresh=0;
function stripXmlTags(s){return (s||'').replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g,'$1').replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&apos;/g,"'").replace(/&nbsp;/g,' ').replace(/&#(\d+);/g,(_,n)=>String.fromCharCode(+n)).replace(/&#x([0-9a-f]+);/gi,(_,n)=>String.fromCharCode(parseInt(n,16))).replace(/<[^>]+>/g,'').replace(/\s+/g,' ').trim()}
// Trim desc to ~200 words on sentence boundary
function inshortsDesc(raw){
  if(!raw)return '';
  let d=raw.replace(/Read more.*$/i,'').replace(/Click here.*$/i,'').replace(/Subscribe.*$/i,'').replace(/\s*\.\.\.\s*$/,'').replace(/\s*…\s*$/,'').trim();
  const words=d.split(/\s+/);
  if(words.length<=200)return d;
  let cut=words.slice(0,200).join(' ');
  const lastDot=Math.max(cut.lastIndexOf('. '),cut.lastIndexOf('! '),cut.lastIndexOf('? '));
  if(lastDot>cut.length*0.3)cut=cut.slice(0,lastDot+1);
  else cut=cut.replace(/[,;:\s]+$/,'')+'.';
  return cut;
}
// Fetch real article content + image from the source URL — targets 150+ words
async function _fetchArticleMeta(url){
  try{
    const ctrl=new AbortController();const t=setTimeout(()=>ctrl.abort(),8000);
    const r=await fetch(url,{signal:ctrl.signal,headers:{'User-Agent':'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36','Accept':'text/html,application/xhtml+xml'}});
    clearTimeout(t);if(!r.ok)return{desc:null,img:null};
    const html=await r.text();
    // Extract og:image
    let img=null;
    const imgPats=[/<meta[^>]+property=["']og:image(?::secure_url)?["'][^>]+content=["']([^"']+)["']/i,/<meta[^>]+content=["']([^"']+)["'][^>]+property=["']og:image(?::secure_url)?["']/i,/<meta[^>]+name=["']twitter:image["'][^>]+content=["']([^"']+)["']/i,/<meta[^>]+content=["']([^"']+)["'][^>]+name=["']twitter:image["']/i];
    for(const p of imgPats){const m=html.match(p);if(m&&m[1]){img=m[1].replace(/&amp;/g,'&');break;}}
    // Extract full article text from <p> tags — aggressive extraction for 10+ lines
    const junkRe=/^(Share|Follow|Subscribe|Copyright|©|Tags|Also Read|ALSO READ|RELATED|Advert|Sign up|Download|Published|Updated|Written by|By\s|Photo:|Image:|Video:|READ MORE|WATCH|Click here|Tap to|Get app|Install|AI Quick Read|Screengrab|Listen to this|We use cookies|Be respectful|TOI community|Accept cookies|Cookie policy|Privacy policy|Terms of|Manage consent)/i;
    const paywallRe=/subscription|subscribe now|sign.?in to continue|create.?an? account|premium content|membership required|paywall|active subscription|you don.?t have any/i;
    // Try multiple content selectors — article first, then main, then full body
    let bestText='';
    const selectors=[/<article[^>]*>([\s\S]*?)<\/article>/gi,/<main[^>]*>([\s\S]*?)<\/main>/gi,/<div[^>]*class="[^"]*(?:article|story|content|post)[^"]*"[^>]*>([\s\S]*?)<\/div>/gi];
    let searchBody=html.slice(0,300000);
    for(const sel of selectors){
      let sm;
      while((sm=sel.exec(searchBody))!==null){
        const paras=[];const pRe=/<p[^>]*>([\s\S]*?)<\/p>/gi;let pm;
        while((pm=pRe.exec(sm[1]))!==null&&paras.length<30){
          const txt=stripXmlTags(pm[1]).trim();
          if(txt.length>20&&!junkRe.test(txt)&&!paywallRe.test(txt))paras.push(txt);
        }
        const candidate=paras.join(' ');
        if(candidate.length>bestText.length)bestText=candidate;
      }
    }
    // Fallback: extract ALL <p> from full page
    if(bestText.split(/\s+/).length<80){
      const paras=[];const pRe=/<p[^>]*>([\s\S]*?)<\/p>/gi;let pm;
      while((pm=pRe.exec(searchBody))!==null&&paras.length<30){
        const txt=stripXmlTags(pm[1]).trim();
        if(txt.length>20&&!junkRe.test(txt)&&!paywallRe.test(txt))paras.push(txt);
      }
      const candidate=paras.join(' ');
      if(candidate.length>bestText.length)bestText=candidate;
    }
    // Also grab og:description as a supplement
    let ogDesc='';
    const descPats=[/<meta[^>]+property=["']og:description["'][^>]+content=["']([^"']*?)["']/i,/<meta[^>]+content=["']([^"']*?)["'][^>]+property=["']og:description["']/i,/<meta[^>]+name=["']description["'][^>]+content=["']([^"']*?)["']/i,/<meta[^>]+content=["']([^"']*?)["'][^>]+name=["']description["']/i];
    for(const p of descPats){const m=html.match(p);if(m&&m[1]&&m[1].trim().length>20){ogDesc=m[1].replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&#39;/g,"'").trim();break;}}
    // Use the longer of article text vs og:description
    let desc=bestText.length>ogDesc.length?bestText:ogDesc;
    // Clean scraped junk prefixes (BBC "Image source, Image caption," etc.)
    if(desc){
      desc=desc.replace(/^(Image source,?\s*)/i,'').replace(/^(Image caption,?\s*)/i,'')
        .replace(/^(Getty Images,?\s*)/i,'').replace(/^(Reuters,?\s*)/i,'')
        .replace(/^(AFP,?\s*)/i,'').replace(/^(AP Photo[^,]*,?\s*)/i,'')
        .replace(/Image source,?\s*/gi,'').replace(/Image caption,?\s*/gi,'')
        .replace(/\(Screengrab\/[^)]*\)\s*/gi,'').replace(/AI Quick Read\s*/gi,'')
        .replace(/Listen to this article\s*/gi,'').replace(/\(File\s*(Photo|Pic)[^)]*\)\s*/gi,'')
        .replace(/To play this video you need to enable JavaScript in your browser\.?\s*/gi,'')
        .replace(/This video can\s*n?o?t be played\s*/gi,'')
        .replace(/\s{2,}/g,' ').trim();
    }
    // Trim to 250 words max
    if(desc){
      const words=desc.split(/\s+/);
      if(words.length>250)desc=words.slice(0,250).join(' ')+'.';
    }
    // Final paywall detection
    if(desc&&paywallRe.test(desc)&&desc.split(/\s+/).length<60)desc=null;
    return{desc:desc||null,img:img||null};
  }catch(e){return{desc:null,img:null}}
}
// ── AI News Rewriter — Brodoit's own journalism engine ──
// Takes raw RSS items and rewrites them as original Inshorts-style summaries
// using Gemini AI. This avoids copyright issues and creates original content.
async function aiRewriteNews(items,cat){
  if(items.length===0)return items;
  if(!geminiKey()){console.log('[NEWS-AI] No GEMINI_API_KEY — using fallback descriptions for '+cat);return items;}
  const batch=items.slice(0,15);
  const sysPrompt=`You are Brodoit News — a respected modern news platform known for making complex stories accessible and interesting. Rewrite each news article as a compelling, detailed summary that a reader can understand without clicking through.

RULES:
1. Each summary must be 58-66 words and 385-405 characters (exactly 9 lines on mobile). This is CRITICAL — aim for exactly 395 characters.
2. Write in a clear, engaging journalistic style — like a skilled reporter telling you what happened over coffee.
3. Open with the single most important fact — the headline brought to life.
4. Include key details: who, what, where, when, why.
5. Add 1 sentence of CONTEXT — background or significance.
6. Do NOT copy original text — rewrite completely in your own words.
7. No opinions or speculation — but do explain implications factually.
8. Make the title punchy, specific, and COMPLETE — under 80 characters. Never truncate with "..." or leave incomplete. Avoid generic titles.
9. CRITICAL: The title and summary MUST be about the EXACT SAME news story. Do NOT mix up or swap articles. Each item's rewritten title must directly relate to its summary.
10. Even if the raw description is empty, use the TITLE to generate a full 60-word summary — expand on the topic knowledgeably.
11. CRITICAL: End each summary with a COMPLETE sentence ending in a period. NEVER end mid-sentence, with "..." or with incomplete thoughts. The last word must be followed by a period.

Respond with a JSON array: [{"id": 0, "title": "punchy rewritten title under 80 chars", "summary": "385-405 character summary ending in a complete sentence"}, ...]
Only output the JSON array, nothing else.`;

  for(let b=0;b<batch.length;b+=5){
    const chunk=batch.slice(b,b+5);
    const chunkJson=chunk.map((it,i)=>({id:b+i,title:it.title||'',rawDesc:(it.desc||'').slice(0,500),source:it.source||'',link:it.link||''}));
    try{
      const r=await _callGemini([{role:'user',content:'Rewrite these '+chunk.length+' news articles as 385-405 character summaries (exactly 9 lines on mobile). Each title MUST match its summary — do NOT mix up stories. Each summary MUST end with a complete sentence and a period. Even if rawDesc is empty, use the title to write a full summary.\n\n'+JSON.stringify(chunkJson)}],{maxTokens:2000,systemPrompt:sysPrompt,purpose:'news'});
      let parsed;
      const jsonMatch=r.reply.match(/\[[\s\S]*\]/);
      if(jsonMatch)parsed=JSON.parse(jsonMatch[0]);
      else parsed=JSON.parse(r.reply);
      for(const rewrite of parsed){
        const idx=rewrite.id;
        if(idx>=0&&idx<batch.length){
          // Coherence check — make sure title and summary share at least 1 significant word
          const origTitle=(batch[idx].title||'').toLowerCase();
          const newTitle=(rewrite.title||'').toLowerCase();
          const newSummary=(rewrite.summary||'').toLowerCase();
          const titleWords=origTitle.split(/\s+/).filter(w=>w.length>4);
          const hasOverlap=titleWords.some(w=>newSummary.includes(w))||titleWords.some(w=>newTitle.includes(w));
          if(rewrite.title&&(hasOverlap||titleWords.length<2))batch[idx].title=rewrite.title;
          // else keep original title if AI title seems unrelated
          if(rewrite.summary&&rewrite.summary.trim().length>30){
            // Verify summary relates to the original title
            const summaryWords=rewrite.summary.toLowerCase().split(/\s+/).filter(w=>w.length>4);
            const titleOverlap=titleWords.some(w=>summaryWords.includes(w))||summaryWords.some(w=>origTitle.includes(w));
            if(titleOverlap||titleWords.length<2)batch[idx].desc=rewrite.summary;
            else console.log('[NEWS-AI] Skipped mismatched summary for "'+batch[idx].title+'"');
          }
          batch[idx].aiRewritten=true;
        }
      }
      console.log('[NEWS-AI] Rewrote '+parsed.length+' articles (batch '+(b/5+1)+') for '+cat);
    }catch(e){
      console.error('[NEWS-AI] Batch '+(b/5+1)+' failed for '+cat+':',e.message);
    }
    if(b+5<batch.length)await new Promise(r=>setTimeout(r,1500));
  }
  // Fallback for any not rewritten — use inshortsDesc on raw RSS content
  for(const it of batch){if(!it.aiRewritten)it.desc=inshortsDesc(it.desc)}
  return items;
}
function parseRSS(xml,sourceUrl){
  const _srcNames={bbci:'BBC',bbc:'BBC',reuters:'Reuters',nytimes:'NYT',techcrunch:'TechCrunch',theverge:'The Verge',venturebeat:'VentureBeat',ndtv:'NDTV',thehindu:'The Hindu',livemint:'Mint',indianexpress:'Indian Express',phys:'Phys.org',nature:'Nature',newscientist:'New Scientist',wired:'Wired',npr:'NPR',technologyreview:'MIT Tech Review'};
  const items=[];let host='';try{const hn=new URL(sourceUrl).hostname.replace(/^www\./,'');const parts=hn.split('.');const raw=parts[0]==='feeds'||parts[0]==='rss'?parts.slice(1,-1).join('.'):parts.slice(0,-1).join('.');const k=raw||parts[0];host=_srcNames[k]||_srcNames[k.split('.')[0]]||k}catch(e){}
  const isAtom=xml.includes('<entry');
  const re=isAtom?/<entry[^>]*>([\s\S]*?)<\/entry>/gi:/<item[^>]*>([\s\S]*?)<\/item>/gi;
  let m;
  while((m=re.exec(xml))!==null&&items.length<15){
    const block=m[1];
    const getTag=(t)=>{const r=block.match(new RegExp('<'+t+'(?:\\s[^>]*)?>([\\s\\S]*?)<\\/'+t+'>','i'));return r?stripXmlTags(r[1]):''};
    const getAttr=(tag,attr)=>{const r=block.match(new RegExp('<'+tag+'[^>]*\\s'+attr+'=["\']([^"\']+)["\']','i'));return r?r[1]:''};
    const title=getTag('title');
    let link=getTag('link');if(!link)link=getAttr('link','href');
    // Prefer the LONGEST content source — content:encoded has full article text, description is usually a blurb
    const _desc=getTag('description'),_summary=getTag('summary'),_encoded=getTag('content:encoded'),_content=getTag('content');
    const _candidates=[_encoded,_content,_desc,_summary].filter(Boolean);
    const rawDesc=_candidates.sort((a,b)=>b.length-a.length)[0]||'';
    const desc=inshortsDesc(rawDesc);
    const date=getTag('pubDate')||getTag('published')||getTag('updated')||getTag('dc:date');
    let img=getAttr('media:content','url')||getAttr('media:thumbnail','url')||getAttr('enclosure','url');
    if(!img){const im=(block.match(/<img[^>]+src=["']([^"']+)["']/i));if(im)img=im[1]}
    if(title&&link)items.push({title:title.slice(0,200),link,desc,date,img:img||null,source:host});
  }
  return items;
}
async function fetchFeed(url){
  try{const ctrl=new AbortController();const t=setTimeout(()=>ctrl.abort(),9000);const r=await fetch(url,{signal:ctrl.signal,headers:{'User-Agent':'Brodoit/1.0 (+https://brodoit.com)','Accept':'application/rss+xml,application/atom+xml,application/xml,text/xml,*/*'}});clearTimeout(t);if(!r.ok)return [];const x=await r.text();return parseRSS(x,url)}catch(e){return []}
}
async function fetchOgImage(url){
  try{const ctrl=new AbortController();const t=setTimeout(()=>ctrl.abort(),5000);const r=await fetch(url,{signal:ctrl.signal,headers:{'User-Agent':'Mozilla/5.0 (compatible; Brodoit/1.0; +https://brodoit.com)','Accept':'text/html,application/xhtml+xml'}});clearTimeout(t);if(!r.ok)return null;const html=await r.text();const head=html.slice(0,80000);const patterns=[/<meta[^>]+property=["']og:image(?::secure_url)?["'][^>]+content=["']([^"']+)["']/i,/<meta[^>]+content=["']([^"']+)["'][^>]+property=["']og:image(?::secure_url)?["']/i,/<meta[^>]+name=["']twitter:image["'][^>]+content=["']([^"']+)["']/i,/<meta[^>]+content=["']([^"']+)["'][^>]+name=["']twitter:image["']/i];for(const p of patterns){const m=head.match(p);if(m&&m[1])return m[1].replace(/&amp;/g,'&')}return null;}catch(e){return null}
}
// Core news fetch+curate for one category — used by API and by scheduled job
// Brodoit's AI journalism engine: fetch RSS → AI-rewrite → copyright-free images
async function curateNewsCategory(cat){
  const feeds=NEWS_FEEDS[cat];
  if(!feeds)return [];
  const results=await Promise.all(feeds.map(fetchFeed));
  let all=results.flat();
  all.sort((a,b)=>{const da=new Date(a.date||0).getTime()||0,db=new Date(b.date||0).getTime()||0;return db-da});
  const seen=new Set();const dedup=[];
  for(const it of all){const k=(it.title||'').toLowerCase().slice(0,60);if(seen.has(k))continue;seen.add(k);dedup.push(it);if(dedup.length>=20)break}
  // Step 1: AI-rewrite all descriptions as original journalism (needs GEMINI_API_KEY)
  await aiRewriteNews(dedup,cat);
  // v27: no article pages are fetched here any more: their text (and photos) belong to the publishers. A story keeps the
  // AI's own rewrite, else the feed's own short description, credited to its source.
  // Step 3: v27: never the publisher's photo; a free Unsplash photo for the category
  const fb=FALLBACK_IMAGES[cat]||FALLBACK_IMAGES.world;
  let fbIdx=0;
  for(const it of dedup){it.img=fb[fbIdx%fb.length];fbIdx++}
  // Step 4: Clean source attribution
  const catLabels={world:'World',india:'India',tech:'AI & Tech',science:'Science',business:'Business'};
  for(const it of dedup){
    it.originalSource=it.source; // v27: the story stays credited to the outlet that reported it (never relabelled "Brodoit")
    it.category=catLabels[cat]||cat;
  }
  // Step 5: Clean junk text then ENFORCE exactly 9 lines via CHARACTER count
  // Mobile: 299px container, 13px font ≈ 47 chars/line, 9 lines = ~423 chars max
  // 421 chars = 9 lines (confirmed), 432 chars = 10 lines (overflow)
  const MAX_CHARS=400;const MIN_CHARS=385;// safe margins for exactly 9 lines
  let shortCount=0;
  for(const it of dedup){
    // Clean cookie/tracking junk that got scraped
    if(it.desc){
      it.desc=it.desc
        .replace(/We use cookies[^.]*\./gi,'')
        .replace(/Be respectful[^.]*\./gi,'')
        .replace(/TOI community guidelines[^.]*\./gi,'')
        .replace(/\(HT_PRINT\)/gi,'')
        .replace(/\(Express file photo\)/gi,'')
        .replace(/\(File photo[^)]*\)/gi,'')
        .replace(/\(Representative image[^)]*\)/gi,'')
        .replace(/Updated:\s*\w+ \d+,\s*\d{4}\s*/gi,'')
        .replace(/Published:\s*\w+ \d+,\s*\d{4}\s*/gi,'')
        .replace(/\s{2,}/g,' ').trim();
    }
    let text=(it.desc||'').trim();
    // v27: a short story stays short: no invented filler sentences
    if(text.length<MIN_CHARS)shortCount++;
    // Trim to MAX_CHARS on sentence boundary
    if(text.length>MAX_CHARS){
      let cut=text.slice(0,MAX_CHARS);
      // Find last sentence boundary within the cut
      const lastDot=Math.max(cut.lastIndexOf('. '),cut.lastIndexOf('! '),cut.lastIndexOf('? '));
      if(lastDot>cut.length*0.5){
        const candidate=cut.slice(0,lastDot+1);
        if(candidate.trim().length>=MIN_CHARS)cut=candidate;
        else cut=text.slice(0,MAX_CHARS).replace(/\s+\S*$/,'').replace(/[,;:\s]+$/,'')+'.';
      }else{
        // No good sentence boundary — cut at last word boundary
        cut=text.slice(0,MAX_CHARS).replace(/\s+\S*$/,'').replace(/[,;:\s]+$/,'')+'.';
      }
      text=cut;
    }
    it.desc=text;
    // Ensure clean ending — trim trailing incomplete fragments, end with period
    if(it.desc){
      it.desc=it.desc.replace(/\s*\.{2,}\s*$/,'').replace(/\s*…\s*$/,'').trim();
      if(!/[.!?]$/.test(it.desc))it.desc=it.desc.replace(/[,;:\s]+$/,'')+'.';
    }
    // TITLE: ensure complete, no CSS truncation — max ~90 chars (fits 2 lines on mobile at 16px)
    // Mobile title container: ~299px at 16px font ≈ ~30 chars/line, 3 lines ≈ 90 chars
    if(it.title&&it.title.length>90){
      // Try to cut at a natural break (colon, dash, comma) before 90 chars
      let t=it.title.slice(0,90);
      const breakPt=Math.max(t.lastIndexOf(' - '),t.lastIndexOf(': '),t.lastIndexOf(' | '),t.lastIndexOf(', '));
      if(breakPt>40)t=t.slice(0,breakPt);
      else t=t.replace(/\s+\S*$/,'');// cut at last word boundary
      it.title=t.trim();
    }
    // Clean title — remove trailing ellipsis, "..." or incomplete endings
    if(it.title){
      it.title=it.title.replace(/\s*\.{2,}\s*$/,'').replace(/\s*…\s*$/,'').replace(/[,;:\-–—|\s]+$/,'').trim();
    }
  }
  const avgC=Math.round(dedup.reduce((s,it)=>s+(it.desc||'').length,0)/Math.max(dedup.length,1));
  const avgW=Math.round(dedup.reduce((s,it)=>s+(it.desc||'').split(/\s+/).length,0)/Math.max(dedup.length,1));
  console.log('[NEWS] Curated '+dedup.length+' items for '+cat+' ('+dedup.filter(x=>x.aiRewritten).length+' AI, '+needsFetch.length+' fetched, '+shortCount+' padded, avg '+avgC+'c/'+avgW+'w)');
  newsCache[cat]={ts:Date.now(),items:dedup};
  return dedup;
}
// ── Scheduled news refresh — every 12 hours, pre-curate ALL categories ──
const NEWS_CATS=['world','india','tech','science','business'];
let _newsRefreshing=false;
async function refreshAllNews(){
  if(_newsRefreshing){console.log('[NEWS] Refresh already in progress, skipping');return}
  _newsRefreshing=true;
  console.log('[NEWS] Starting scheduled news refresh for all categories...');
  const start=Date.now();
  for(const cat of NEWS_CATS){
    try{await curateNewsCategory(cat);console.log('[NEWS] Refreshed '+cat+' ('+((newsCache[cat]||{}).items||[]).length+' items)')}
    catch(e){console.error('[NEWS] Failed to refresh '+cat+':',e.message)}
    // Small delay between categories to be polite to RSS servers
    await new Promise(r=>setTimeout(r,2000));
  }
  newsLastFullRefresh=Date.now();
  _newsRefreshing=false;
  console.log('[NEWS] Full refresh done in '+((Date.now()-start)/1000).toFixed(1)+'s');
}
// Refresh on startup (after 10s to let server boot) then every 12 hours
setTimeout(()=>refreshAllNews(),10000);
setInterval(()=>refreshAllNews(),12*60*60*1000);
// API endpoint — serves from cache, falls back to live fetch
// Image proxy for share card canvas (avoids CORS)
app.get('/api/img-proxy',async(req,res)=>{
  const url=req.query.url;
  if(!url){return res.status(400).send('Missing url param')}
  try{
    const r=await fetch(url,{headers:{'User-Agent':'Mozilla/5.0','Accept':'image/*'},redirect:'follow',signal:AbortSignal.timeout(8000)});
    if(!r.ok)return res.status(502).send('Image fetch failed');
    const ct=r.headers.get('content-type')||'image/jpeg';
    res.set('Content-Type',ct);res.set('Cache-Control','public,max-age=3600');res.set('Access-Control-Allow-Origin','*');
    const buf=Buffer.from(await r.arrayBuffer());
    res.send(buf);
  }catch(e){res.status(502).send('Proxy error')}
});

app.get('/api/news',async(req,res)=>{
  let cat=(req.query.cat||'').toLowerCase();
  // Unified single feed — merge all categories
  if(!cat||cat==='all'){
    let allItems=[];
    for(const c of NEWS_CATS){
      const cached=newsCache[c];
      if(cached&&Date.now()-cached.ts<12*60*60*1000){
        allItems.push(...cached.items);
      }else{
        try{const items=await curateNewsCategory(c);allItems.push(...items)}catch(e){}
      }
    }
    // Sort by date, dedup by title, take top 25
    allItems.sort((a,b)=>{const da=new Date(a.date||0).getTime()||0,db=new Date(b.date||0).getTime()||0;return db-da});
    const seen=new Set();const dedup=[];
    for(const it of allItems){const k=(it.title||'').toLowerCase().slice(0,50);if(seen.has(k))continue;seen.add(k);dedup.push(it);if(dedup.length>=25)break}
    return res.json({items:dedup,cat:'all',cached:true,refreshedAt:Date.now()});
  }
  // Legacy per-category fallback
  if(cat==='ai'||cat==='technology')cat='tech';
  else if(cat==='global'||cat==='movies')cat='world';
  const feeds=NEWS_FEEDS[cat];
  if(!feeds)return res.json({items:[],cat});
  const c=newsCache[cat];
  if(c&&Date.now()-c.ts<12*60*60*1000){
    return res.json({items:c.items,cat,cached:true,refreshedAt:c.ts,nextRefresh:c.ts+12*60*60*1000});
  }
  const items=await curateNewsCategory(cat);
  res.json({items,cat,cached:false,refreshedAt:newsCache[cat]?.ts||Date.now(),nextRefresh:Date.now()+12*60*60*1000});
});
// Manual refresh endpoint (for admin use) — clears cache so next fetch gets fresh AI-rewritten content
app.post('/api/news/refresh',async(req,res)=>{
  // Clear old cache so fresh content is served immediately
  for(const cat of NEWS_CATS) delete newsCache[cat];
  refreshAllNews();
  res.json({ok:true,message:'News refresh started — cache cleared'});
});

