function mgPlayLevel(key,lvl){
  const cur=(S.mg.progress[key]||{level:1}).level||1;
  if(lvl>cur){toast('\\u{1F512} Reach Level '+lvl+' first','err');return}
  S.mg.progress[key]={...(S.mg.progress[key]||{level:1,xp:0,best:0}),level:lvl};
  const fnMap={math:'mgMathStart',schulte:'mgSchulteStart',sudoku:'mgSudokuStart',spatial:'mgSpatialStart',memory:'mgMemoryStart',reaction:'mgReactionStart',word:'mgWordStart',stroop:'mgStroopStart',nback:'mgNbackStart',colormatch:'mgColorMatchStart'};
  const fn=fnMap[key];if(!fn)return;
  mgCountdown(fn,key);
}
var _mgCdNames={math:'Math Sprint',schulte:'Schulte Grid',sudoku:'Sudoku 6\\u00D76',spatial:'Pattern Recall',memory:'Memory Tap',reaction:'Reaction Time',word:'Word Sprint',stroop:'Stroop Challenge',nback:'N-Back',colormatch:'Color Match'};
function mgCountdown(startFnName,gameKey){
  if(S._mgCdTimer){clearInterval(S._mgCdTimer);S._mgCdTimer=null}
  S.mgPlay={game:'countdown',countNum:3,startFn:startFnName,gameKey:gameKey};
  _mgSound('tap');render();
  S._mgCdTimer=setInterval(function(){
    var p=S.mgPlay;if(!p||p.game!=='countdown'){clearInterval(S._mgCdTimer);S._mgCdTimer=null;return}
    p.countNum--;
    if(p.countNum<0){
      clearInterval(S._mgCdTimer);S._mgCdTimer=null;
      var fn=window[p.startFn];if(typeof fn==='function')fn();
      return;
    }
    _mgSound('tap');render();
  },800);
}

// ── 6x6 Sudoku (2x3 boxes) ───────────────────────────────────────────
// Procedurally generated 6x6 puzzles. More challenging than 4x4,
// perfect for mobile brain training. 2-row x 3-col boxes.
function _sudokuValid(g,r,c,n){
  for(let i=0;i<6;i++){if(g[r*6+i]===n||g[i*6+c]===n)return false}
  const br=Math.floor(r/2)*2,bc=Math.floor(c/3)*3;
  for(let i=0;i<2;i++)for(let j=0;j<3;j++)if(g[(br+i)*6+(bc+j)]===n)return false;
  return true;
}
function _sudokuSolve(g){
  const grid=g.slice();
  const solve=()=>{
    for(let r=0;r<6;r++)for(let c=0;c<6;c++){
      if(grid[r*6+c]===0){
        const nums=[1,2,3,4,5,6];
        for(let i=nums.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[nums[i],nums[j]]=[nums[j],nums[i]]}
        for(const n of nums){
          if(_sudokuValid(grid,r,c,n)){grid[r*6+c]=n;if(solve())return true;grid[r*6+c]=0}
        }
        return false;
      }
    }
    return true;
  };
  solve();return grid;
}
function _sudokuGenerate(clueCount){
  const full=_sudokuSolve(new Array(36).fill(0));
  const puzzle=full.slice();
  const cells=Array.from({length:36},(_,i)=>i);
  for(let i=cells.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[cells[i],cells[j]]=[cells[j],cells[i]]}
  let removed=0;const target=36-clueCount;
  for(const idx of cells){
    if(removed>=target)break;
    puzzle[idx]=0;removed++;
  }
  return{initial:puzzle,solution:full};
}
function mgSudokuStart(){
  const lvl=(S.mg.progress.sudoku&&S.mg.progress.sudoku.level)||1;
  const clues=Math.max(14,24-lvl*2);
  const{initial,solution}=_sudokuGenerate(clues);
  S.mgPlay={game:'sudoku',level:lvl,_baseLevel:lvl,initial,grid:initial.slice(),solution,selected:-1,timeStart:Date.now(),mistakes:0,done:false};
  render();
}
function mgSudokuTap(i){const p=S.mgPlay;if(!p||p.game!=='sudoku'||p.done)return;if(p.initial[i]!==0)return;p.selected=i;render()}
function mgSudokuPlace(n){
  const p=S.mgPlay;if(!p||p.game!=='sudoku'||p.done||p.selected<0)return;
  if(p.initial[p.selected]!==0)return;
  if(n===0){p.grid[p.selected]=0;render();return}
  if(p.solution[p.selected]!==n){p.mistakes++;toast('⚠️ Not quite','err');render();return}
  p.grid[p.selected]=n;
  let complete=true;for(let i=0;i<36;i++)if(p.grid[i]===0){complete=false;break}
  if(complete){
    p.done=true;
    const seconds=Math.round((Date.now()-p.timeStart)/1000);
    p.elapsed=seconds;
    const xpGain=Math.max(20,80-seconds-p.mistakes*5);
    const cur=S.mg.progress.sudoku||{level:1,xp:0,best:0};
    const newXp=(cur.xp||0)+xpGain;
    const newLevel=Math.min(10,1+Math.floor(newXp/100));
    const newBest=cur.best===0?seconds:Math.min(cur.best,seconds);
    S.mg.progress.sudoku={level:newLevel,xp:newXp,best:newBest};
    api('/mindgym/progress',{method:'POST',body:JSON.stringify({game:'sudoku',xp:xpGain,best:newBest,level:newLevel,seconds})}).catch(function(){});
    toast('✨ Solved in '+seconds+'s — +'+xpGain+' XP');
  }
  render();
}
function mgSudokuClose(){if(S.mgPlay&&S.mgPlay.game==='sudoku'){S.mgPlay=null;render()}}

// ── Word Sprint (anagram unscrambler, 90-sec timer, length-squared scoring) ──
