    h+='<span style="font:600 11px var(--sans);background:'+p.c+'20;color:'+p.c+';padding:2px 7px;border-radius:0">'+(window.Cards?'<i class="tk-pri tk-'+t.priority+'"></i>':p.d+' ')+t.priority+'</span>';
