app.get('/admin/beta-signups',adminAuth,(req,res)=>{
  const rows=db.prepare('SELECT id,name,email,source,added_to_console,created_at,added_at FROM beta_signups ORDER BY created_at DESC').all();
  const escH=s=>(s||'').replace(/[<>&]/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;'})[c]);
  const tableRows=rows.map((r,i)=>`<tr style="border-bottom:1px solid #d7d3d3"><td style="padding:10px 8px">${i+1}</td><td style="padding:10px 8px;font-weight:600">${escH(r.name||'—')}</td><td style="padding:10px 8px;font-family:monospace;font-size:13px">${escH(r.email)}</td><td style="padding:10px 8px;color:#7d7979;font-size:12px">${escH(r.source||'direct')}</td><td style="padding:10px 8px">${r.added_to_console?'<span style="color:#1F1E1C;font-weight:600">✅ added</span>':'<span style="color:#C8922A;font-weight:600">⏳ pending</span>'}</td><td style="padding:10px 8px;color:#7d7979;font-size:12px">${escH((r.created_at||'').split(' ')[0])}</td></tr>`).join('');
  res.send(`<!doctype html><html><head><title>Brodoit · Beta Signups</title><meta name="viewport" content="width=device-width,initial-scale=1"><style>body{font-family:-apple-system,Segoe UI,sans-serif;background:#f3f2f2;color:#201e1d;margin:0;padding:24px;max-width:980px;margin:0 auto}h1{font-size:22px;margin:0 0 6px}.sub{color:#7d7979;font-size:13px;margin-bottom:18px}.bar{display:flex;gap:8px;margin-bottom:16px}.btn{padding:8px 14px;background:#0F1115;color:#FFD27A;text-decoration:none;border-radius:0;font-size:13px;font-weight:600}.btn.sec{background:#fff;color:#0F1115;border:1px solid #d7d3d3}table{width:100%;border-collapse:collapse;background:#fff;border:1px solid #d7d3d3;border-radius:0;overflow:hidden}th{text-align:left;padding:12px 8px;background:#f3f2f2;font-size:11px;text-transform:uppercase;letter-spacing:.06em;color:#7d7979;font-weight:600;border-bottom:1px solid #d7d3d3}.note{margin-top:18px;padding:14px;background:#f3f2f2;border:1px solid #d7d3d3;border-radius:0;font-size:13px;color:#1F1E1C;line-height:1.5}</style></head><body><h1>Brodoit · Beta Signups</h1><div class="sub">${rows.length} total — ${rows.filter(r=>!r.added_to_console).length} pending Play Console add</div><div class="bar"><a class="btn" href="/admin/testers?token=${escH(req.query.token||'')}">Activity dashboard →</a><a class="btn sec" href="/beta">View signup page →</a></div><table><thead><tr><th>#</th><th>Name</th><th>Play email</th><th>Source</th><th>Added to console</th><th>Joined</th></tr></thead><tbody>${tableRows||'<tr><td colspan="6" style="padding:32px;text-align:center;color:#9CA3AF">No signups yet. Share <b>brodoit.com/beta</b>.</td></tr>'}</tbody></table><div class="note"><b>Workflow:</b> emails arriving here = paste into Play Console → Closed testing → Testers list, then mark as added: <code>POST /api/beta-mark-added</code> with {email}.</div></body></html>`);
});

app.post('/api/beta-mark-added',adminAuth,(req,res)=>{
  const email=String(req.body.email||'').trim().toLowerCase();
  if(!email)return res.status(400).json({ok:false,error:'email required'});
  db.prepare("UPDATE beta_signups SET added_to_console=1,added_at=datetime('now') WHERE email=?").run(email);
  res.json({ok:true});
});

